import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.B8xISX-C.js";const m=JSON.parse('{"title":"Testing","description":"","frontmatter":{"title":"Testing"},"headers":[],"relativePath":"guide/testing.md","filePath":"guide/testing.md"}'),s={name:"guide/testing.md"};function d(n,e,r,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><p>This page covers the loop of checking a mod, playing it with computer players, importing it and testing it in the game.</p><h2 id="the-loop" tabindex="-1">The loop <a class="header-anchor" href="#the-loop" aria-label="Permalink to &quot;The loop&quot;">​</a></h2><ol><li>Edit files. An editor with the JSON Schemas flags mistakes as you type. <code>npx carina-modkit vscode</code> writes the schemas and the VS Code settings for every mod folder.</li><li><code>npx carina-modkit check mods/&lt;mod&gt;</code> runs the game&#39;s own checks.</li><li><code>npx carina-modkit run mods/&lt;mod&gt; --turns 50</code> plays computer players under your rules.</li><li><code>npx carina-modkit pack mods/&lt;mod&gt;</code> writes the <code>.carinamod</code>.</li><li>Import it in the game, or use dev mode.</li></ol><h2 id="check" tabindex="-1">check <a class="header-anchor" href="#check" aria-label="Permalink to &quot;check&quot;">​</a></h2><p><code>check</code> prints what the game would say on import. Every issue names the severity, a code, the mod and file, the JSON path in the file and what was expected. <code>check</code> stops at the first stage that fails, so fixing one issue can show the next.</p><ul><li><code>--json</code> prints the report as JSON.</li><li><code>--with &lt;folder&gt;</code> adds a mod that yours needs, when it is not in a sibling folder. See <a href="/carina-mod-template/guide/dependencies">Dependencies and compatibility</a>.</li></ul><p>The <a href="/carina-mod-template/check">Check my mod</a> page runs the same importer in the browser. It checks one mod at a time against the built-in rules.</p><h2 id="run" tabindex="-1">run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;run&quot;">​</a></h2><p><code>run</code> plays computer players under your rules and prints the ruleset hash, a digest of the final state and one line per application, building, weapon or race the mod adds, with how many empires, colonies or designs use it. A line with a count of 0 means the computer players never used it.</p><ul><li><code>--turns N</code> sets the number of turns. The default is 50.</li><li><code>--seed N</code> sets the game seed. The default is 1.</li><li><code>--players N</code> sets the number of empires, 2 to 8. The default is 4.</li><li><code>--json</code> prints the result as JSON.</li></ul><p>A broken game invariant makes <code>run</code> fail with the invariant named.</p><h2 id="pack" tabindex="-1">pack <a class="header-anchor" href="#pack" aria-label="Permalink to &quot;pack&quot;">​</a></h2><p><code>pack</code> writes <code>dist/&lt;id&gt;-&lt;version&gt;.carinamod</code> in the working folder and prints its sha256 and the three hashes. <code>--out &lt;dir&gt;</code> writes to another folder. <a href="/carina-mod-template/guide/updates">Releasing an update</a> explains the hashes.</p><h2 id="import" tabindex="-1">Importing into the game <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Importing into the game {#import}&quot;">​</a></h2><ol><li>Open MODS on the main menu. The INSTALLED tab lists the mods on your device.</li><li>Press IMPORT and pick the <code>.carinamod</code> file. In a desktop browser, drop the file or the mod folder on the screen instead.</li><li>Select the mod. The details box shows what it holds, what it adds and changes, and any issues, the same list <code>check</code> prints.</li><li>For a rules mod, open New Game, press RULES, switch the mod on and press ACCEPT. The picker shows the order the mods compose in and lets you pick a winner when two mods change the same value.</li><li>A cosmetic pack is switched on or off with the ON/OFF switch in its row on the INSTALLED tab instead.</li></ol><h2 id="dev-mode" tabindex="-1">Dev mode <a class="header-anchor" href="#dev-mode" aria-label="Permalink to &quot;Dev mode {#dev-mode}&quot;">​</a></h2><p>Dev mode reads a mod folder directly, so a change needs no packing.</p><ol><li>Open MODS, then DEV MODE. Or add <code>?moddev</code> to the end of the game&#39;s address.</li><li>Press FOLDER and pick <code>mods/&lt;mod&gt;</code>. Chrome and Edge read the folder again within a second of each save. Firefox and Safari cannot watch a folder: press FOLDER again after editing.</li></ol><p>The game reads the folder, compiles it and lists the issues.</p><p>The status line says what a change needs:</p><ul><li><code>Rules changed: RESTART or LOAD to play them.</code></li><li><code>Only text or art changed: no restart needed.</code></li></ul><p>The buttons:</p><ul><li>RESTART starts your last new game again, with the same setup and seed, under your rules. Without an earlier game it opens New Game.</li><li>LOAD opens the Load dialog. A game saved with the mod as it is now loads with it. After a rules change such a save no longer matches, so use RESTART.</li><li>COPY copies the issues as text.</li><li>POLICY shows the content policy.</li></ul><p>New Game keeps using the mod&#39;s rules until the page is reloaded.</p><h2 id="testing-an-old-save" tabindex="-1">Testing an old save <a class="header-anchor" href="#testing-an-old-save" aria-label="Permalink to &quot;Testing an old save&quot;">​</a></h2><p>See <a href="/carina-mod-template/guide/updates#testing-an-old-save">Releasing an update</a>.</p>',27)])])}const u=t(s,[["render",d]]);export{m as __pageData,u as default};
